import { ADD, DELETE, EDIT } from "../types/productTypes";

const productReducer = (state, action) => {
  switch (action.type) {
    case ADD:
      return {};
    case EDIT:
      return {};
    case DELETE:
      return {};

    default:
      return state;
  }
};

export { productReducer };
